function CollectionsView({
  orders,
  customers,
  products,
  onRegisterPayment,
  onCopyMessage,
}: {
  orders: Order[];
  customers: Customer[];
  products: Product[];
  onRegisterPayment: (orderId: string, amount?: number) => void;
  onCopyMessage: (message: string) => void;
}) {
  const pending = orders.filter((order) => getOrderBalance(order) > 0);
  const [partialAmounts, setPartialAmounts] = useState<Record<string, string>>({});

  return (
    <div className="table-panel">
      <div className="panel-header">
        <div>
          <h2 className="panel-title">Cuenta corriente y saldos</h2>
          <div className="panel-kicker">Recordatorios manuales listos para WhatsApp.</div>
        </div>
      </div>
      <div className="table-wrap">
        <table className="table">
          <thead>
            <tr>
              <th>Pedido</th>
              <th>Cliente</th>
              <th>Total</th>
              <th>Saldo</th>
              <th>Vence</th>
              <th>Dias</th>
              <th>Mensaje</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {pending.map((order) => {
              const customer = findCustomer(customers, order.customerId);
              const message = generateCollectionMessage(order, customers);
              return (
                <tr key={order.id}>
                  <td>#{order.number}</td>
                  <td>
                    <div className="strong">{customer?.businessName}</div>
                    <div className="muted">{customer?.zone}</div>
                  </td>
                  <td>{formatCurrency(getOrderTotal(order))}</td>
                  <td>{formatCurrency(getOrderBalance(order))}</td>
                  <td>{formatDate(order.dueDate)}</td>
                  <td>
                    {(() => {
                      const days = getDaysOverdue(order.dueDate);
                      const cls = days === 0 ? "ok" : days <= 3 ? "warning" : "critical";
                      return (
                        <span className={`overdue-badge ${cls}`}>
                          {days === 0 ? "Al dia" : `${days}d`}
                        </span>
                      );
                    })()}
                  </td>
                  <td>
                    <button className="button secondary" onClick={() => onCopyMessage(message)} title="Copiar mensaje de cobranza">
                      <Copy size={16} />
                      Copiar
                    </button>
                  </td>
                  <td>
                    <div className="row-actions">
                      <input
                        className="qty-input partial-payment-input"
                        type="number"
                        min={1}
                        placeholder="Monto"
                        value={partialAmounts[order.id] ?? ""}
                        onChange={(e) => setPartialAmounts({ ...partialAmounts, [order.id]: e.target.value })}
                        aria-label="Monto parcial"
                      />
                      <button
                        className="button secondary"
                        onClick={() => {
                          const amt = Number(partialAmounts[order.id]);
                          if (amt > 0) {
                            onRegisterPayment(order.id, amt);
                            setPartialAmounts({ ...partialAmounts, [order.id]: "" });
                          }
                        }}
                        title="Pago parcial"
                      >
                        Parcial
                      </button>
                      <button className="button primary" onClick={() => onRegisterPayment(order.id)} title="Pago total">
                        <Check size={16} />
                        Total
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {pending.length === 0 && <div className="empty">No hay saldos pendientes.</div>}
      <div style={{ height: 12 }} />
      <div className="message-box">
        Esta pantalla es una de las de mayor valor percibido: convierte deuda dispersa
        en una lista accionable con mensaje listo para enviar.
      </div>
    </div>
  );
}

function ReportsView({
  state,
  metrics,
}: {
  state: DemoState;
  metrics: ReturnType<typeof getDashboardMetrics>;
}) {
  const categorySales = state.products.map((product) => {
    const sold = state.orders.reduce((sum, order) => {
      const line = order.lines.find((item) => item.productId === product.id);
      return sum + (line ? line.quantity * line.unitPrice : 0);
    }, 0);
    return { label: product.name, value: sold };
  });
  const maxSale = Math.max(...categorySales.map((item) => item.value), 1);
  const converted = state.inquiries.filter((inquiry) => inquiry.status === "convertida").length;

  return (
    <>
      <div className="grid metrics">
        <Metric icon={Store} label="Clientes" value={String(state.customers.length)} note="Base demo activa" />
        <Metric icon={Package} label="Productos" value={String(state.products.length)} note={`${metrics.lowStock} con stock bajo`} />
        <Metric icon={MessageCircle} label="Conversion consultas" value={`${converted}/${state.inquiries.length}`} note="Medible para venta consultiva" />
        <Metric icon={WalletCards} label="Deuda visible" value={formatCurrency(metrics.receivable)} note="Saldo pendiente total" />
      </div>
      <div className="grid two">
        <div className="panel">
          <div className="panel-header">
            <div>
              <h2 className="panel-title">Productos con movimiento</h2>
              <div className="panel-kicker">Barra simple para discutir valor, no BI pesado.</div>
            </div>
          </div>
          <div className="list">
            {categorySales
              .filter((item) => item.value > 0)
              .sort((a, b) => b.value - a.value)
              .map((item) => (
                <div key={item.label}>
                  <div className="split-row">
                    <span className="strong">{item.label}</span>
                    <span>{formatCurrency(item.value)}</span>
                  </div>
                  <div style={{ background: "#edf1f7", borderRadius: 999, height: 10, marginTop: 8 }}>
                    <div
                      style={{
                        background: "#2563eb",
                        borderRadius: 999,
                        height: 10,
                        width: `${Math.max(8, (item.value / maxSale) * 100)}%`,
                      }}
                    />
                  </div>
                </div>
              ))}
          </div>
        </div>
        <div className="panel">
          <div className="panel-header">
            <div>
              <h2 className="panel-title">Reportes que suman rapido</h2>
              <div className="panel-kicker">Prioridad para pilotos pagos.</div>
            </div>
          </div>
          <div className="list">
            <InfoRow label="Ventas del dia" value={formatCurrency(metrics.todaySales)} />
            <InfoRow label="Pedidos pendientes" value={String(metrics.pendingOrders)} />
            <InfoRow label="Entregados sin cobrar" value={String(metrics.deliveredUnpaid)} />
            <InfoRow label="Consultas abiertas" value={String(metrics.openInquiries)} />
            <InfoRow label="Stock bajo" value={String(metrics.lowStock)} />
          </div>
        </div>
      </div>
    </>
  );
}

